import { Effect } from "effect"
// Minimized from packages/tui/src/app.tsx: scoped acquisition + render callback.
declare const acquire: Effect.Effect<{ destroy(): void }>
declare function render(view: () => unknown): Promise<void>
declare function Provider(props: { children?: unknown }): any
declare function App(): any
export const program = Effect.scoped(effect {
  const renderer = try Effect.acquireRelease(acquire, r => Effect.sync(() => r.destroy()))
  try Effect.tryPromise(() => render(() => <Provider><App /></Provider>))
  return renderer
})

